html:
{% if doc.mode_of_travel == "Private Vehicle" %}

    <!-- GARAMOND FONT & 12PT SIZE -->
    <style>
        body, .print-format, .letter-head, .row, .section-break, .column-break, .printedby, p, ul, li, b, span, div {
            font-family: Garamond, 'Times New Roman', Times, serif !important;
            font-size: 12pt !important;
        }
        .printedby {
            font-size: 10pt !important;
            font-family: Garamond, 'Times New Roman', Times, serif !important;
        }
    </style>

    <!-- HEADER (keep as is) -->
    <div id="header-html" class="hidden-pdf">
        {%- if letter_head and not no_letterhead -%}
            <div class="letter-head">
                {{ letter_head }}
            </div>
        {%- endif -%}
    </div>

    <!-- MAIN CONTENT WRAPPER -->
    <div style="min-height:900px; display:flex; flex-direction:column; justify-content:flex-start;">
    
        <!-- REQUEST ID & TITLE HEADING CENTERED -->
        <div style="text-align:center; margin-bottom:5px;">
        <h1 style="text-decoration: underline; font-size: 22px; font-weight: bold; margin: 0;">
            Vehicle Request
        </h1>
    </div>

    <div style="text-align:center; margin-bottom:18px;">
        <span style="font-size:18px; font-weight:bold; text-decoration: underline;">
            Private Vehicle Mileage Claim Approved
        </span>
    </div>


    <!-- ADDRESS BLOCK AND DATE -->
    <div style="text-align:center; margin-bottom:18px;">
        <span style="text-decoration: underline; font-size: 14px;">
            Claimed Date: {{ doc.posting_date }}
        </span>
    </div>


    <!-- LETTER BODY -->
    <p>
        As per the approved request to take private vehicle with reference: <b>{{ doc.name }}</b>, 
        the following employees:
    </p>
    <ol style="margin: 4px 0 4px 20px;">
        <li>
            <b>{{ doc.employee_name }} (Applicant)
            {% if doc.grade %} ({{ doc.grade }}){% endif %}
            {% if doc.designation %}, {{ doc.designation }}{% endif %}
        </li>
        {% for row in doc.employee_details %}
            <li>
                {{ row.employee_name }}
                {% if row.employee_grade %} ({{ row.employee_grade }}){% endif %}
                {% if row.department %}, {{ row.department }}{% endif %}
            </b></li>
        {% endfor %}
    </ol>
    <p>
        are scheduled to travel to <b>{{ doc.place }}</b> from <b>{{ doc.from_date }}</b> to <b>{{ doc.to_date }}</b> via private vehicle.
        The purpose of this travel is: <b>{{ doc.purpose }}</b>.<br>
        <br>Therefore, I request mileage claim for this travel as per the existing regulation.
    </p>
<!-- Approval Details: Placed right after main letter content, with little or no top margin -->
<div style="width:100%; margin-top:350px;">
    <div class="row section-break">
        <div class="col-xs-4 column-break" style="text-align: left;">
            <b>Applied By:</b><br/>
            {% if doc.owner and frappe.db.get_value("Employee",{"user_id":doc.owner},"name") %}
                {% set name, designation, branch = frappe.db.get_value('Employee', {'user_id': doc.owner}, ['employee_name', 'designation', 'branch']) %}
                {{ name }} <br/> {{ designation }} <br/> {{ branch }} <br/>
            {% else %}
                Please Verify Via System
            {% endif %}
        </div>
        <div class="col-xs-4 column-break" style="text-align: center;">
            <b>Verified By:</b><br/>
            {% if doc.verifier and frappe.db.get_value("Employee",{"user_id":doc.verifier},"name") %}
                {% set name, designation, branch = frappe.db.get_value('Employee', {'user_id': doc.verifier}, ['employee_name', 'designation', 'branch']) %}
                {{ name }} <br/> {{ designation }} <br/> {{ branch }}
            {% else %}
                Please Verify Via System
            {% endif %}
        </div>
        <div class="col-xs-4 column-break" style="text-align: right;">
            <b>Approved By:</b><br/>
            {% if doc.approver and frappe.db.get_value("Employee",{"user_id":doc.approver},"name") %}
                {% set name, designation, branch = frappe.db.get_value('Employee', {'user_id': doc.approver}, ['employee_name', 'designation', 'branch']) %}
                {{ name }} <br/> {{ designation }} <br/> {{ branch }}
            {% else %}
                Please Verify Via System
            {% endif %}
        </div>
    </div>
    <br>
    <div class="printedby" style="margin-top: 30px; font-size: 10px;">
        This print is system generated and should be considered VALID only with appropriate seal and/or signature.
        Printed by {{ frappe.user }} on {{ frappe.utils.nowdate() }} at {{ frappe.utils.nowtime() }}
    </div>
</div>

{% else %}
    <div style="text-align:center; margin-top:100px;">
        <b>This Mileage Claim Print Format is only available for Private Vehicle requests.</b>
    </div>
{% endif %}
